 if(existing){const state=JSON.parse(existing);if(state.status==='applied'){verify(state);console.log('Already applied; no changes.');process.exit(0)}throw Error('Previous recovery state exists. Use --uninstall if interrupted; preserve/move the backup folder before a new installation.')}
