 for(const entry of changes)if(entry.beforeHash!==null){const data=read(entry.file);if(hash(data)!==entry.beforeHash)throw Error('Source changed during preparation');write(backup+'/files/'+entry.file,data);if(hash(read(backup+'/files/'+entry.file))!==entry.beforeHash)throw Error('Backup failed')}
 save(state);for(const entry of changes){const data=read(entry.file);if((data===null?null:hash(data))!==entry.beforeHash)throw Error('Source changed during preparation: '+entry.file)}
 try{for(const entry of changes)write(entry.file,entry.after===null?null:Buffer.from(entry.after,'base64'));state.status='applied';save(state)}catch(error){restore(state);state.status='restored';save(state);throw error}
 console.log('Time-travel dependency fixture repaired. No production source changed; no restart or dependency reinstall needed. See docs/development/test-baseline.md. Keep '+backup+' for rollback.');
